<script setup lang="ts">
import { computed, reactive, watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api, asApiError, type ApiError } from '../api/client';
import { ref, shallowRef } from 'vue';
import { useRemote } from '../composables/useRemote';
import { parseM4Filters,m4Query,m4Names,shipmentStates,syncStates,aftersaleStates,aftersaleTypes,sourceStates,upstreamStates } from '../domain/m4';
import { formatFen,shanghaiTime } from '../domain/m1';
import ErrorPanel from '../components/ErrorPanel.vue';
import PagePagination from '../components/PagePagination.vue';
import M4Navigation from '../components/M4Navigation.vue';
const props=defineProps<{kind:'shipment'|'aftersale'|'notification'}>();
const route=useRoute(),router=useRouter();const filters=computed(()=>parseM4Filters(route.query,props.kind));
const form=reactive({storeId:'',state:'',syncState:'',type:'',sourceState:'',upstreamState:'',unread:''});
const shipments=useRemote(()=>api.listShipments(filters.value));const aftersales=useRemote(()=>api.listAftersales(filters.value));const notifications=useRemote(()=>api.listNotifications(filters.value));const stores=useRemote(()=>api.listStores(100,0));
const queue=computed(()=>props.kind==='shipment'?shipments:props.kind==='aftersale'?aftersales:notifications);
const title=computed(()=>props.kind==='shipment'?'物流中心':props.kind==='aftersale'?'售后中心':'站内通知');
watch(()=>route.fullPath,()=>{for(const key of Object.keys(form) as (keyof typeof form)[])form[key]=filters.value[key]??'';void queue.value.load();},{immediate:true});void stores.load();
function apply(){void router.push({path:route.path,query:m4Query({...filters.value,...form,offset:0},props.kind)});}
function paginate(offset:number,limit:number){void router.push({path:route.path,query:m4Query({...filters.value,offset,limit},props.kind)});}
const reading=ref('');const readError=shallowRef<ApiError|null>(null);const readKeys=new Map<string,string>();
async function read(id:string){if(reading.value)return;const context=route.fullPath;reading.value=id;readError.value=null;let key=readKeys.get(id);if(!key){key=globalThis.crypto.randomUUID();readKeys.set(id,key);}try{const result=await api.readNotification(id,key);if(route.fullPath===context&&notifications.data.value)notifications.data.value={...notifications.data.value,items:notifications.data.value.items.map(item=>item.id===id?result:item)};}catch(cause){if(route.fullPath===context)readError.value=asApiError(cause);}finally{reading.value='';}}
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">履约与经营 / Mock</p><h1>{{ title }}</h1><p class="muted">独立记录来源、工作流及权威状态 · Asia/Shanghai</p></div><el-button :loading="queue.loading.value" @click="queue.load">刷新权威状态</el-button></div><M4Navigation /><p class="scope-hint">仅合成 Mock 数据 / 待授权。发货与退款结果以后台独立查询为准。</p><section class="panel filter-panel"><form data-testid="m4-filters" class="filter-form" @submit.prevent="apply"><label>店铺<select v-model="form.storeId" name="storeId"><option value="">全部可见店铺</option><option v-for="store in stores.data.value?.items" :key="store.id" :value="store.id">{{ store.displayName }}</option></select></label><template v-if="kind==='shipment'"><label>物流状态<select v-model="form.state" name="state"><option value="">全部</option><option v-for="s in shipmentStates" :key="s" :value="s">{{ m4Names[s] }}</option></select></label><label>下游回填<select v-model="form.syncState" name="syncState"><option value="">全部</option><option v-for="s in syncStates" :key="s" :value="s">{{ m4Names[s] }}</option></select></label></template><template v-if="kind==='aftersale'"><label v-for="field in [{key:'state',label:'本地工作流',options:aftersaleStates},{key:'type',label:'售后类型',options:aftersaleTypes},{key:'sourceState',label:'来源状态',options:sourceStates},{key:'upstreamState',label:'供应商状态',options:upstreamStates}]" :key="field.key">{{ field.label }}<select v-model="form[field.key as 'state']" :name="field.key"><option value="">全部</option><option v-for="s in field.options" :key="s" :value="s">{{ m4Names[s] }}</option></select></label></template><label v-if="kind==='notification'">阅读状态<select v-model="form.unread" name="unread"><option value="">全部</option><option value="true">未读</option><option value="false">已读</option></select></label><el-button native-type="submit" type="primary">查询</el-button></form><ErrorPanel v-if="stores.error.value" :error="stores.error.value" title="店铺范围读取失败"><el-button @click="stores.load">重试店铺</el-button></ErrorPanel><p v-if="stores.data.value&&stores.data.value.total>100" class="help-text">显示前 100 个可见店铺，可使用含 storeId 的范围链接。</p></section><ErrorPanel v-if="readError" :error="readError" /><section class="panel table-panel" :aria-busy="queue.loading.value"><div v-if="queue.loading.value" role="status" class="data-state"><el-skeleton :rows="5" animated /><p>正在读取{{ title }}…</p></div><ErrorPanel v-else-if="queue.error.value" :error="queue.error.value" :title="queue.error.value.status===404?'记录不存在或不在访问范围':queue.error.value.status===403?'无权访问当前范围':'列表读取失败'"><el-button @click="queue.load">重试</el-button></ErrorPanel><div v-else-if="!queue.data.value?.items.length" data-testid="m4-empty" class="data-state"><h2>暂无匹配记录</h2><p>调整筛选或在关联详情中生成合成 Mock 事件。</p></div><div v-else class="table-scroll"><table v-if="kind==='shipment'" class="data-table"><thead><tr><th>包裹 / 运单</th><th>来源 / 本地物流</th><th>下游权威回填</th><th>关联 / 更新时间</th></tr></thead><tbody><tr v-for="item in shipments.data.value?.items" :key="item.id"><td><RouterLink class="text-link" :to="`/shipments/${item.id}`">{{ item.externalShipmentId }}</RouterLink><small>{{ item.trackingNumber }} · 版本 {{ item.trackingVersion }} · 数量 {{ item.qty }}</small></td><td>{{ m4Names[item.sourceState] }} / {{ m4Names[item.state] }}<small>{{ item.sourceState }} / {{ item.state }}</small></td><td>{{ m4Names[item.currentSync?.state??'NOT_SENT'] }}<small>{{ item.currentSync?.platformAck??'尚无权威回执' }}</small><small>{{ item.currentSync?.lastErrorCode }}</small></td><td><RouterLink class="text-link" :to="`/purchases/${item.purchaseOrderId}`">查看采购</RouterLink><small>{{ shanghaiTime(item.updatedAt) }}</small></td></tr></tbody></table><table v-if="kind==='aftersale'" class="data-table"><thead><tr><th>售后 / 类型</th><th>来源平台状态</th><th>本地工作流</th><th>供应商权威状态</th><th>申请退款 / 时间</th></tr></thead><tbody><tr v-for="item in aftersales.data.value?.items" :key="item.id"><td><RouterLink class="text-link" :to="`/aftersales/${item.id}`">{{ item.sourceCaseId }}</RouterLink><small>{{ m4Names[item.type] }} · 数量 {{ item.qty }}</small></td><td>{{ m4Names[item.sourceState] }}<small>{{ item.sourceState }}</small></td><td>{{ m4Names[item.state] }}</td><td>{{ m4Names[item.upstreamState] }}<small>{{ item.upstreamState }}</small></td><td>{{ formatFen(item.requestedRefundFen) }} CNY<small>{{ shanghaiTime(item.updatedAt) }}</small></td></tr></tbody></table><table v-if="kind==='notification'" class="data-table"><thead><tr><th>通知类别 / 安全摘要</th><th>时间（上海）</th><th>阅读状态</th><th>关联</th></tr></thead><tbody><tr v-for="item in notifications.data.value?.items" :key="item.id"><td>{{ item.category }}<small>{{ item.code }}</small></td><td>{{ shanghaiTime(item.createdAt) }}</td><td>{{ item.readAt?'已读':'未读' }}<el-button v-if="!item.readAt" data-testid="read-notification" :disabled="!!reading" :loading="reading===item.id" @click="read(item.id)">标记已读</el-button></td><td><RouterLink class="text-link" :to="`/orders/${item.salesOrderId}`">查看订单</RouterLink></td></tr></tbody></table></div><PagePagination v-if="queue.data.value" :total="queue.data.value.total" :limit="filters.limit" :offset="filters.offset" :loading="queue.loading.value" @change="paginate" /></section></div></template>
